getLtopDistance.body:
if (distanceNum !== null && distanceNum >= 1 && distanceNum <= 99) {
            const url = getResource(this.locale, Resource.Audio, "leaning-tower-of-pizza/distances/" + distanceNum + ".mp3");
            return url;
        }
        const url = getResource(this.locale, Resource.Audio, "leaning-tower-of-pizza/" + getRandomElement(this.ltop.distances));
        return url;

getLtopLieScore.body:
if (score !== null && this.ltop.lieScores[score]) {
            const url = getResource(this.locale, Resource.Audio, "leaning-tower-of-pizza/" + getRandomElement(this.ltop.lieScores[score]));
            return url;
        }
        const allScores = Object.values(this.ltop.lieScores).flat();
        const url = getResource(this.locale, Resource.Audio, "leaning-tower-of-pizza/" + getRandomElement(allScores));
        return url;

getLtopComment.body:
let commentArray;
        if (score <= 3) {
            commentArray = this.ltop.comments.lowScore;
        } else if (score <= 5) {
            commentArray = this.ltop.comments.midScore;
        } else if (score <= 7) {
            commentArray = this.ltop.comments.decentScore;
        } else if (score === 8) {
            commentArray = this.ltop.comments.score8;
        } else if (score === 9) {
            commentArray = this.ltop.comments.score9;
        } else {
            commentArray = this.ltop.comments.score10;
        }
        const url = getResource(this.locale, Resource.Audio, "leaning-tower-of-pizza/" + getRandomElement(commentArray));
        return url;

